    const duration = Date.now() - startTime;

    // Assert performance criteria
    expect(duration).toBeGreaterThanOrEqual(1000);
    expect(duration).toBeLessThan(15000); // Rule 10: General performance limit
    expect(duration).toBeLessThan(5000);  // Specific TC requirement: within 5000 ms
