  await featurePage.usernameInput.fill('STANDARD_USER');
  await featurePage.passwordInput.fill(testData.password);
  await featurePage.loginButton.click();

  // Expect to remain on the login page and show error
  await expect(page).toHaveURL(testData.baseURL);
  await expect(featurePage.errorMessageContainer).toBeVisible();
